    if Wait ~= nil and Kind(Wait) ~= "function" then Raise(0, 0); end;
    local function Cancel()
        Dead = true;
        Chunks = {};
        ContainerKey, ModuleKey, Remote, Salt = nil, nil, nil, nil;
