    local Resolve;
    Resolve = function(PathA, PathB)
        if Dead then Raise(0, 0); end;
        local Entry = Catalog[Text(PathA) .. ":" .. Text(PathB)];
        if not Entry then
            if Public then return Public(PathA, PathB); end;
            Dead = true;
            Raise(0, 0);
        end;
        local Id, Base = Entry[1], Entry[2];
        if not Chunks[Id] then
            local Deadline = Clock() + 30;
            while Fetching[Id] do
                if Fetching[Id] == Running() or not Wait or Clock() > Deadline then Cancel(); Raise(0, 0); end;
